def analyze_sequence(stmts):
    def sequentially(a, b):
        def the_sequence(env, succeed, fail):
            def a_succeed(a_value, fail2):
                if is_return_value(a_value):
                    return succeed(a_value, fail2)
                else:
                    return b(env, succeed, fail2)
            return a(env, a_succeed, fail)
        return the_sequence
    def loop(first_fun, rest_funs):
        if is_none(rest_funs):
            return first_fun
        else:
            return loop(sequentially(first_fun, head(rest_funs)),
                        tail(rest_funs))
    funs = map(analyze, stmts)
    if is_none(funs):
        return lambda env, succeed, fail: succeed(None, fail)
    else:
        return loop(head(funs), tail(funs))

