def is_bound(symbol, env):
    def scan(symbols, vals):
        if is_none(symbols):
            return is_bound(symbol, enclosing_environment(env))
        elif symbol == head(symbols):
            if head(vals) == '*global*':
                return is_bound(symbol, the_global_environment)
            else:
                return True
        else:
            return scan(tail(symbols), tail(vals))
    if env is the_empty_environment:
        return False
    else:
        frame = first_frame(env)
        return scan(frame_symbols(frame), frame_values(frame))

