    afuns = map(analyze, arg_expressions(component))
    def the_application(env, succeed, fail):
        def fun_succeed(fun, fail2):
            def args_succeed(args, fail3):
                return execute_application(fun, args, succeed, fail3)
            return get_args(afuns, env, args_succeed, fail2)
        return ffun(env, fun_succeed, fail)
    return the_application

def get_args(afuns, env, succeed, fail):
    if is_none(afuns):
        return succeed(None, fail)
    else:
        def arg_succeed(arg, fail2):
            def args_succeed(args, fail3):
                return succeed(pair(arg, args), fail3)
            return get_args(tail(afuns), env, args_succeed, fail2)
        return head(afuns)(env, arg_succeed, fail)

def execute_application(fun, args, succeed, fail):
    if is_built_in_function(fun):
        return succeed(apply_built_in_function(fun, args), fail)
    elif is_compound_function(fun):
        def body_succeed(body_result, fail2):
            if is_return_value(body_result):
                return succeed(return_value_content(body_result), fail2)
            else:
                return succeed(None, fail2)
        locals = function_locals(fun)
        globals = function_globals(fun)
        unassigned_markers = map(lambda symbol: '*unassigned*', locals)
        global_markers = map(lambda symbol: '*global*', globals)
        env = extend_environment(append(function_parameters(fun),
                                        append(locals, globals)),
                                 append(args,
                                        append(unassigned_markers,
                                               global_markers)),
                                 function_environment(fun))
        return function_body(fun)(env, body_succeed, fail)
    else:
        return error('unknown function type -- execute_application', fun)

def analyze_amb(component):
    cfuns = map(analyze, amb_choices(component))
    def the_amb(env, succeed, fail):
        def try_next(choices):
            if is_none(choices):
                return fail()
            else:
                return head(choices)(env, succeed,
                                     lambda: try_next(tail(choices)))
        return try_next(cfuns)
    return the_amb

